) as v(code, name, pos, grade, dept, start, nid4, dob, phone, phone4, site, etype, remark, resign)
on conflict (emp_code) do update set
  full_name = excluded.full_name,
  position = excluded.position,
  grade = excluded.grade,
  department_id = coalesce(excluded.department_id, "PFormPro_employees".department_id),
  start_date = coalesce(excluded.start_date, "PFormPro_employees".start_date),
  national_id_last4 = coalesce(excluded.national_id_last4, "PFormPro_employees".national_id_last4),
  birth_date = coalesce(excluded.birth_date, "PFormPro_employees".birth_date),
  phone = coalesce(excluded.phone, "PFormPro_employees".phone),
  phone_last4 = coalesce(excluded.phone_last4, "PFormPro_employees".phone_last4),
  work_site = excluded.work_site,
  employment_type = excluded.employment_type,
  remark = coalesce(excluded.remark, "PFormPro_employees".remark),
  active = excluded.active,
  evaluate = case when excluded.active = false then false
                  when "PFormPro_employees".active = false then true
                  else "PFormPro_employees".evaluate end,
  emp_status = case when excluded.active = false then 'resigned' else 'working' end;

notify pgrst, 'reload schema';

-- 4) ตรวจผล
select emp_status, active, evaluate, count(*) from "PFormPro_employees" group by 1, 2, 3 order by 1, 2, 3;
select d.name as division, p.dept_code, p.name as department, count(e.*) filter (where e.active) as working, count(e.*) filter (where not e.active) as resigned
from "PFormPro_departments" p left join "PFormPro_divisions" d on d.id = p.division_id left join "PFormPro_employees" e on e.department_id = p.id
group by 1, 2, 3 order by 1, 2;
